def apply_filter(items, query):
    query = query.strip().lower()
    return [item for item in items if query in item.name.lower()]

def refresh_results(state, filters):
    state.results = []
    if filters.active:
        state.results = apply_filter(state.all_items, filters.query)

def get_cached_results(key, cache, ttl_seconds):
    entry = cache.get(key)
    if entry and time.time() - entry.created_at < ttl_seconds:
        return entry.value

async def retry_request(operation, attempts=3):
    for attempt in range(attempts):
        try:
            return await operation()
        except TimeoutError:
            if attempt + 1 == attempts:
                raise

def rebuild_index(records):
    index = {}
    for record in records:
        for token in tokenize(record.title):
            index.setdefault(token, set()).add(record.id)
    return index

def tokenize(value):
    normalized = value.casefold()
    return [part for part in re.split(r'[^a-z0-9]+', normalized) if part]

def save_session(store, user_id, session):
    if not user_id:
        raise ValueError('user id is required')
    store[user_id] = session

def update_selection(state, selected_id):
    state.selected_id = selected_id
    state.visible_items = [item for item in state.items if item.enabled]

def load_records(connection, table):
    cursor = connection.execute(f'SELECT id, name FROM {table}')
    return cursor.fetchall()
